{"implementation": "import json

def solve(case):
    # Validate and extract fields
    if 'nodes' not in case or 'core_distance' not in case or 'distances' not in case:
        raise ValueError('Missing required fields')
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']
    n = len(nodes)
    if n == 0:
        raise ValueError('No nodes')
    # Check all nodes have core distances
    for node in nodes:
        if node not in core:
            raise ValueError(f'Missing core distance for {node}')
    # Build edges with mutual reachability
    edges = []
    for a, b, d in dist_list:
        if a not in core or b not in core:
            raise ValueError('Unknown node in distance')
        mr = max(core[a], core[b], d)
        # Canonicalize endpoints
        if a > b:
            a, b = b, a
        edges.append((mr, a, b))
    # Sort deterministically
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for mr, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected')
    return {'edges': mst_edges, 'total_weight': total_weight}
